const crypto = require('crypto');
const data = ($input.first().json || {}).query || {};
const secret = $env.AUTH_TOKEN_SECRET || '';
const invoice = String(data.invoice || '').trim();
const company = String(data.company ?? '1').trim();
const action = String(data.action ?? '').trim();
const exp = String(data.exp ?? '').trim();
const sig = String(data.sig || '').trim();
const resend = String(data.resend || '') === '1';
let ok = false, mode = 'invalid';
if (action === 'approve' && exp) {
  const expected = crypto.createHmac('sha256', secret).update(`${company}.${invoice}.approve.${exp}`).digest('base64url');
  ok = sig === expected && Math.floor(Date.now() / 1000) <= Number(exp);
  if (ok) mode = 'v2';
} else if (!action && invoice.length > 0) {
  // legacy link minted before 2026-09-05 (HMAC over invoice number only)
  const legacy = crypto.createHmac('sha256', secret).update(invoice).digest('base64url');
  ok = sig === legacy;
  if (ok) mode = 'legacy';
}
return [{ json: { ok, invoice, company: company || '1', mode, resend, decision: ok ? 'APPROVE' : '' } }];

const inv = $input.first()?.json;
function buildClientInvoiceHtml(inv) {
  const money = (v) => Number(v ?? 0).toLocaleString('en-CA', { style: 'currency', currency: 'CAD' });
  const company = inv?.company_name ?? 'Ireh Construction';
  const primary = inv?.brand_primary_color ?? '#1a3a5c';
  const accent = inv?.brand_accent_color ?? '#2563eb';
  const addressLine = [inv?.street_address, inv?.city, `${inv?.province ?? ''} ${inv?.postal_code ?? ''}`].filter(Boolean).join(', ');
  const typeMap = { 'DEPOSIT': 'Deposit', 'PROGRESS_BILLING': 'Progress billing', 'CHANGE_ORDER': 'Change order',
                    'FINAL': 'Final', 'Deposit': 'Deposit', 'Progress': 'Progress billing',
                    'Change Order': 'Change order', 'Final': 'Final' };
  const typeLabel = typeMap[inv?.invoice_type] || inv?.invoice_type || '';
  const holdbackPct = inv?.retention_rate != null ? Math.round(Number(inv.retention_rate) * 100) : 10;
  const taxLines = [];
  if (inv?.gst_reg_number) taxLines.push(`<div class="co">GST # ${inv.gst_reg_number}</div>`);
  if (inv?.pst_reg_number) taxLines.push(`<div class="co">PST # ${inv.pst_reg_number}</div>`);
  const pct = inv?.billing_percentage;
  const basis = inv?.billed_basis;
  const lineLabel = inv?.description
    ? String(inv.description)
    : (pct != null && basis != null)
      ? `${typeLabel} \u2014 ${String(Number(pct))}% of revised contract value (${money(basis)})`
      : typeLabel || 'Services';
  const billTo = [inv?.bill_street, inv?.bill_city, inv?.bill_province ? `${inv?.bill_province} ${inv?.bill_postal ?? ''}` : inv?.bill_postal]
    .map(s => (s || '').toString().trim()).filter(Boolean);
  const showBillTo = billTo.length > 0;
  const payLines = (inv?.payment_instructions || '').split('\n').filter(s => s.trim().length > 0);
  return `<!doctype html><html><head><meta charset="utf-8"><style>
  body { font-family: Helvetica, Arial, sans-serif; color: #1e293b; margin: 2rem; }
  .header { display: flex; justify-content: space-between; border-bottom: 2px solid ${primary}; padding-bottom: 1rem; }
  .title { font-size: 1.5rem; font-weight: 700; color: ${primary}; }
  .co { color: #64748b; font-size: .85rem; }
  .row { display: flex; justify-content: space-between; padding: .4rem 0; }
  .total { font-size: 1.3rem; font-weight: 700; border-top: 2px solid ${primary}; margin-top: 1rem; padding-top: 1rem; }
  .billto { border-left: 3px solid ${accent}; padding-left: .75rem; margin: .75rem 0; color: #334155; }
  .pay { border-top: 1px solid #cbd5e1; margin-top: 1.5rem; padding-top: .75rem; color: #475569; font-size: .9rem; }
  @media print { body { margin: 0; } }
</style></head><body>
  <div class="header">
    <div><div class="title">${company}</div><div class="co">${addressLine}</div><div class="co">${inv?.phone ?? ''}</div>${taxLines.join('')}</div>
    <div style="text-align:right"><div class="title">Invoice</div><div>${inv?.invoice_number ?? ''}</div><div>Issued: ${inv?.issued_date ?? ''}</div><div>Due: ${inv?.due_date ?? ''}</div></div>
  </div>
  <p><strong>Project:</strong> ${inv?.project_name ?? ''}</p>
  <p><strong>Customer:</strong> ${inv?.customer_name ?? ''}${inv?.customer_company ? ` (${inv.customer_company})` : ''}</p>
  ${showBillTo ? `<div class="billto"><strong>Bill to</strong><br>${billTo.join('<br>')}</div>` : ''}
  <p><strong>Type:</strong> ${typeLabel || '\u2014'}</p>
  <div class="row"><span>${lineLabel}</span><span>${money(inv?.net_amount)}</span></div>
  ${Number(inv?.gst_amount) ? `<div class="row"><span>GST</span><span>${money(inv?.gst_amount)}</span></div>` : ''}
  ${Number(inv?.pst_amount) ? `<div class="row"><span>PST</span><span>${money(inv?.pst_amount)}</span></div>` : ''}
  ${Number(inv?.holdback_amount) ? `<div class="row"><span>Holdback (${holdbackPct}% retained)</span><span>${money(inv?.holdback_amount)}</span></div>` : ''}
  <div class="total">Total due ${money(inv?.amount_due)}</div>
  ${payLines.length ? `<div class="pay"><strong>How to pay</strong><br>${payLines.join('<br>')}</div>` : ''}
</body></html>`; }
// stored canonical HTML (previewed == sent) wins when present
if (inv?.last_client_html) return [{ json: { ...inv, html: inv.last_client_html } }];
return [{ json: { ...inv, html: buildClientInvoiceHtml(inv) } }];

const row = $('Lookup Invoice').first().json;
const num = row?.invoice_number ?? '';
const email = row?.email ?? '';
const resent = row?.email_sent_at ? ' (resent)' : '';
const html = `<html><body style="font-family:Helvetica,Arial,sans-serif;margin:2rem;color:#1e293b"><h1 style="color:#16a34a">Invoice sent${resent}</h1><p>Invoice <strong>${num}</strong> was emailed to <strong>${email}</strong>.</p><p>You can close this page.</p></body></html>`;
return [{ json: { html } }];

const q = ($('approve-invoice').first().json || {}).query || {};
const row = $input.first()?.json || {};
const when = row?.email_sent_at ? ' on ' + String(row.email_sent_at).slice(0, 10) : '';
const base = row?.portal_base_url || 'https://n8n2.ordrnow.com';
const params = new URLSearchParams();
['invoice', 'company', 'exp', 'action', 'sig'].forEach((k) => { if (q[k]) params.set(k, String(q[k])); });
params.set('resend', '1');
const resendUrl = `${base}/webhook/approve-invoice?${params.toString()}`;
const html = `<html><body style="font-family:Helvetica,Arial,sans-serif;margin:2rem;color:#1e293b"><h1 style="color:#d97706">Already sent</h1><p>Invoice <strong>${row?.invoice_number ?? ''}</strong> was already emailed to <strong>${row?.email ?? ''}</strong>${when}.</p><p>If the client did not receive it, you can send it again:</p><p><a href="${resendUrl}" style="display:inline-block;background:#16a34a;color:#fff;padding:.6rem 1.2rem;border-radius:6px;text-decoration:none">Send this invoice again</a></p></body></html>`;
return [{ json: { html } }];

const crypto = require('crypto');
const data = ($input.first().json || {}).query || {};
const secret = $env.AUTH_TOKEN_SECRET || '';
const invoice = String(data.invoice || '').trim();
const company = String(data.company ?? '1').trim();
const action = String(data.action ?? '').trim();
const exp = String(data.exp ?? '').trim();
const sig = String(data.sig || '').trim();
let ok = false, mode = 'invalid';
if (action === 'reject' && exp) {
  const expected = crypto.createHmac('sha256', secret).update(`${company}.${invoice}.reject.${exp}`).digest('base64url');
  ok = sig === expected && Math.floor(Date.now() / 1000) <= Number(exp);
  if (ok) mode = 'v2';
}
return [{ json: { ok, invoice, company: company || '1', mode, decision: ok ? 'REJECT' : '' } }];

const v = $('Verify Signature (Reject)').first()?.json;
const invoice = String(v?.invoice ?? '');
const html = `<html><body style="font-family:Helvetica,Arial,sans-serif;margin:2rem;color:#1e293b"><h1 style="color:#dc2626">Invoice not sent</h1><p>Invoice <strong>${invoice}</strong> was <strong>not</strong> emailed to the client \u2014 you rejected the preview.</p><p>You can close this page.</p></body></html>`;
return [{ json: { html } }];
